.ornament,
.location1,
.location2,
.location3,
.location4,
.location5,
.location6{
  opacity: 0 !important;
}
.ornament:hover,
.location1:hover,
.location2:hover,
.location3:hover,
.location4:hover,
.location5:hover,
.location6:hover{
  opacity: 1 !important;
}

.hint{
  pointer-events: none; /* делает элемент полностью некликабельным */
}

.coin {
  position: relative;
  cursor: default;
}

.ring,
.eye,
.obsidian,
.sword,
.coin,
.light,
.shell,
.mask,
.tear {
  position: relative;
}

/* базовый стиль тултипа */
.ring::after,
.eye::after,
.obsidian::after,
.sword::after,
.coin::after,
.light::after,
.shell::after,
.mask::after,
.tear::after {
  position: absolute;
  left: 220%;
  top: 35%;
  transform: translateX(-50%);
  background: #f3e6c8;
  border: 2px solid #6b4b2a;
  color: #4a2f16;
  padding: 5px 6px;
  border-radius: 6px;
  font-size: 12px;
  font-family: georgia;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease, transform 0.2s ease;
  z-index: 999;
}

/* появление */
.ring:hover::after,
.eye:hover::after,
.obsidian:hover::after,
.sword:hover::after,
.coin:hover::after,
.light:hover::after,
.shell:hover::after,
.mask:hover::after,
.tear:hover::after {
  opacity: 1;
  transform: translateX(-50%) translateY(-5px);
}

.coin::after {
  content: "Golden coin";
}

.light::after {
  content: "Amulet with light";
}

.shell::after {
  content: "Broken shell";
}

.tear::after {
  content: "Crystal tear";
}

.eye::after {
  content: "Eye of darkness";
}

.obsidian::after {
  content: "Obsidian tear";
}

.sword::after {
  content: "The sword of peace";
}

.ring::after {
  content: "Old Magic Storage Ring";
}

.mask::after {
  content: "The Mask of Great Magician";
}


